from dataclasses import dataclass
from . import email as email_lib, store
from shop import audit
@dataclass
class LoginResult:
    ok: bool
    error: str = ''
def reject(reason):
    audit.log_event('login_rejected', reason=reason)
    return LoginResult(False, reason)
def login(raw_email, password):
    if not raw_email.strip(): return reject('missing_email')
    try: address = email_lib.normalize(raw_email)
    except ValueError: return reject('invalid_email')
    if not store.check(address, password): return reject('wrong_credentials')
    return LoginResult(True)

