from . import email as email_lib
from . import store


def recovery_target(raw_email):
    """Address to send a reset link to, or None when there is no such account."""
    try:
        address = email_lib.normalize(raw_email)
    except ValueError:
        return None
    return address if address in store.ACCOUNTS else None

