class Cart:
    def __init__(self):
        self.items = {}

    def add(self, sku, qty=1, price=0.0):
        count, _ = self.items.get(sku, (0, price))
        self.items[sku] = (count + qty, price)

    def total(self):
        return round(sum(count * price for count, price in self.items.values()), 2)

