import unittest

from shop.auth import login, recovery, signup, store


class AuthTests(unittest.TestCase):
    def setUp(self):
        store.clear()
        signup.signup('Ann.Lee@Example.COM', 'correct horse')

    def test_signup_keeps_local_part_case(self):
        self.assertIn('Ann.Lee@example.com', store.ACCOUNTS)

    def test_signup_rejects_malformed_email(self):
        for bad in ('', 'no-at-sign', '@example.com', 'a@'):
            with self.assertRaises(ValueError):
                signup.signup(bad, 'long enough password')

    def test_login_success(self):
        self.assertTrue(login.login('Ann.Lee@example.com', 'correct horse').ok)

    def test_login_wrong_password(self):
        self.assertEqual(login.login('Ann.Lee@example.com', 'nope').error, 'wrong_credentials')

    def test_login_empty_email_does_not_crash(self):
        self.assertFalse(login.login('', 'whatever').ok)

    def test_login_malformed_email_does_not_crash(self):
        self.assertFalse(login.login('no-at-sign', 'x').ok)

    def test_recovery_unknown_and_malformed(self):
        self.assertIsNone(recovery.recovery_target('nobody@example.com'))
        self.assertIsNone(recovery.recovery_target(''))
